uv run --with pillow python -c 'from collections import deque
from PIL import Image


def check(path):
    im = Image.open(path).convert("RGBA")
    w, h = im.size
    px = im.load()

    def idx(x, y):
        return y * w + x

    cminx, cminy, cmaxx, cmaxy = w, h, 0, 0
    for y in range(h):
        for x in range(w):
            if px[x, y][3] > 200:
                cminx = min(cminx, x)
                cminy = min(cminy, y)
                cmaxx = max(cmaxx, x)
                cmaxy = max(cmaxy, y)
    cw, ch = cmaxx - cminx, cmaxy - cminy
    seen = bytearray(w * h)
    bg = bytearray(w * h)
    holes = 0
    for y in range(h):
        for x in range(w):
            i = idx(x, y)
            if seen[i] or px[x, y][3] != 0:
                continue
            q = deque([(x, y)])
            seen[i] = 1
            comp = []
            touch = False
            while q:
                cx, cy = q.popleft()
                comp.append((cx, cy))
                touch = touch or cx in (0, w - 1) or cy in (0, h - 1)
                for nx, ny in ((cx - 1, cy), (cx + 1, cy), (cx, cy - 1), (cx, cy + 1)):
                    if 0 <= nx < w and 0 <= ny < h and not seen[idx(nx, ny)] and px[nx, ny][3] == 0:
                        seen[idx(nx, ny)] = 1
                        q.append((nx, ny))
            if touch or len(comp) >= 7000:
                for cx, cy in comp:
                    bg[idx(cx, cy)] = 1
            else:
                holes += 1
    bad = 0
    highlight = 0
    for y in range(h):
        for x in range(w):
            head = cminx + 0.22 * cw <= x <= cminx + 0.58 * cw and cminy <= y <= cminy + 0.28 * ch
            hand = (
                cminx + 0.02 * cw <= x <= cminx + 0.32 * cw
                and cminy + 0.18 * ch <= y <= cminy + 0.52 * ch
            )
            if not (head or hand):
                continue
            i = idx(x, y)
            r, g, b, a = px[x, y]
            if a == 255 and min(r, g, b) >= 250 and head:
                highlight += 1
            if bg[i] or a == 255:
                continue
            if any(
                0 <= nx < w and 0 <= ny < h and bg[idx(nx, ny)]
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1))
            ):
                continue
            bad += 1
    print(path, "holes", holes, "interior", bad, "highlight", highlight)
    assert holes == 0 and bad == 0 and highlight >= 200, path


for name in (
    "docs/assets/retornatus-mascot.webp",
    "docs/assets/retornatus-mascot-neon.webp",
    "docs/assets/retornatus-mascot-square.webp",
):
    check(name)
print("head and hand silhouette opaque")'

